import {CHARACTERS,MODES,createGame} from './game.js';
import {network} from './net.js';
import {loadArt,sprite,drawSprite} from './art.js';
import {loadMapArt,prepareMapArt,paintSourceMap} from './map-art.js';
import {loadCharacterMotion,drawCharacterMotion} from './character-motion.js';
import {GAME_NAME,GAME_TAGLINE} from './branding.js';

const $=(s,root=document)=>root.querySelector(s),app=$('#app'),modalRoot=$('#modal-root');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconFiles={rooms:'rooms',person:'person',shop:'shop',trophy:'records',settings:'settings',back:'exit',plus:'plus',help:'help',check:'ready',sound:'sound',chat:'chat',team:'team',lock:'lock',search:'search',refresh:'refresh',home:'home'};
const ico=name=>iconFiles[name]?`<span class="ui-icon painted-icon" aria-hidden="true"><img src="./assets/ui/icons/${iconFiles[name]}.png" alt=""></span>`:`<span class="ui-icon" aria-hidden="true">${({play:'▷',pause:'Ⅱ',close:'×',next:'→'})[name]||'✦'}</span>`;
const char=id=>CHARACTERS.find(c=>c.id===id)||CHARACTERS[0],mode=id=>MODES.find(m=>m.id===id)||MODES[0];
const draftMapNames={courtyard:'庭院 · 自定义技术试稿',town:'街区 · 自定义技术试稿',factory:'工场 · 自定义技术试稿'};
let mapDirectory={maps:[],draftMaps:[]},mapDirectoryStatus='loading',mapDirectoryError='',mapDirectoryPromise=null;
const sourceMapCache=new Map();
const allMaps=()=>[...mapDirectory.maps,...mapDirectory.draftMaps];
const mapInfo=(id,fallback=null)=>allMaps().find(m=>m.id===id)||fallback||state?.rooms?.find(r=>r.map===id)?.mapInfo||(state?.currentRoom?.map===id?state.currentRoom.mapInfo:null)||null;
const mapName=(id,fallback=null)=>mapInfo(id,fallback)?.name||draftMapNames[id]||(id==='source-201'?'中国城01':String(id));
const maxSeats=r=>Math.max(1,Number(r?.maxSeats??r?.max??r?.mapInfo?.maxSeats??mapInfo(r?.map)?.maxSeats)||8);
const mapDimensions=info=>info?.width&&info?.height?`${info.width}列 × ${info.height}行`:'尺寸待核对';
const sourceKind=info=>info?.kind==='source-map';
const canPreviewMap=info=>!!info?.playable&&!(info.artCoverage?.missingCount>0);
function unavailableMapReason(info){if(info?.playable&&info.artCoverage?.missingCount>0)return '场景美术制作中（缺'+info.artCoverage.missingCount+'类）';return ({SOURCE_FILE_MISSING:'地图文件缺失',SOURCE_RULE_UNSUPPORTED:'此地图玩法尚未接入',SOURCE_UNKNOWN_ELEMENT:'部分地图资源尚未齐全',SOURCE_SPAWNS:'出生位置尚待核对',SOURCE_SPAWN_BLOCKED:'出生位置尚待核对',SOURCE_FOOTPRINT_BOUNDS:'建筑占地尚待核对',SOURCE_HASH_MISMATCH:'地图文件校验未通过'})[info?.unavailableCode]||'地图数据尚待核对';}
async function loadMapDirectory(force=false){
  if(mapDirectoryStatus==='ready'&&!force)return mapDirectory;
  if(mapDirectoryPromise)return mapDirectoryPromise;
  mapDirectoryStatus='loading';mapDirectoryError='';
  mapDirectoryPromise=network.maps().then(data=>{if(!Array.isArray(data.maps)||!Array.isArray(data.draftMaps))throw new Error('地图目录格式不正确。');mapDirectory={maps:data.maps,draftMaps:data.draftMaps};mapDirectoryStatus='ready';return mapDirectory;}).catch(error=>{mapDirectoryStatus='error';mapDirectoryError=error.message;throw error;}).finally(()=>mapDirectoryPromise=null);
  return mapDirectoryPromise;
}
async function loadSourceMap(id){
  if(sourceMapCache.has(id))return sourceMapCache.get(id);
  const pending=network.map(id).then(data=>{const map=data.sourceMap;if(!map||map.kind!=='source-map'||map.id!==id||!Number.isInteger(map.width)||!Number.isInteger(map.height)||map.layers?.length!==3)throw new Error('该地图的完整预览数据暂不可用。');return map;}).catch(error=>{sourceMapCache.delete(id);throw error;});
  sourceMapCache.set(id,pending);return pending;
}
function mapDetails(id){const info=mapInfo(id);showModal('地图来源与核对状态',`<h3>${esc(mapName(id))}</h3><p>${mapDimensions(info)} · 最多 ${info?.maxSeats||'待核对'} 人</p>${sourceKind(info)?'<div class="notice">源数据候选：地图格值、建筑占地与出生坐标取自已留存的社区客户端数据；尚未确认腾讯原始版本，也未完成原版像素碰撞与美术锚点验收。</div>':'<div class="notice">自定义技术试稿，仅供功能测试，不是原版地图。</div>'}<p>${canPreviewMap(info)?'当前可用模式：'+(info.playableModes||[]).map(id=>mode(id).name).join('、'):esc(unavailableMapReason(info))}</p><p><a href="./docs/SOURCE_MAP_RUNTIME_INTERFACE.md" target="_blank" rel="noopener">查看来源、核对依据和未完成事项</a></p>`,'<button class="btn primary" data-action="close-modal">了解了</button>','map-info');}

const clock=seconds=>`${Math.floor(Math.max(0,seconds)/60).toString().padStart(2,'0')}:${Math.floor(Math.max(0,seconds)%60).toString().padStart(2,'0')}`;
const cosmetics=[{id:'jade',name:'玉青原色',desc:'保留角色手绘原色'},{id:'sunset',name:'暖霞映衣',desc:'偏暖显示滤镜'},{id:'moon',name:'月下清辉',desc:'冷色显示滤镜'}];
const STORAGE_KEY='qqtang-rebuild-v2';
let prefs={sound:true,volume:.2,character:'maomao',skin:'jade',records:[]};try{prefs={...prefs,...JSON.parse(localStorage.getItem('qqtang-rebuild-v2')||'{}')};}catch{}
if(!CHARACTERS.some(c=>c.id===prefs.character))prefs.character='maomao';
if(!cosmetics.some(c=>c.id===prefs.skin))prefs.skin='jade';
prefs.records=mergeRecords(prefs.records);
prefs.volume=Math.max(0,Math.min(1,Number(prefs.volume)||0));
let state=null,view='login',channel='free',modeFilter='all',connected=false,modal='',modalGameId=null,lastFocus=null,toastTimer,lastFingerprint='',draftCharacter=prefs.character,busy=false,audio=null,pressed=new Set(),held=null,lastInput=0,lastRoomId=null,lastChat='';
const finishSeen=new Set();
const playerName=p=>p.isBot?char(p.character).name+' · AI':p.name;
const characterDisplayName=name=>({毛毛:'道童',阿莎:'月影',悟空:'山岳',泰坦:'莲花'})[name]||name;
const endReasonText=reason=>({'team-eliminated':'一方队伍全部离场','all-players-out':'全体角色离场','all-waves-cleared':'全部波次已通关','time-limit':'对局时间结束',objective:'达成模式目标'})[reason]||'对局结束';
const room=()=>state?.currentRoom;
const me=()=>room()?.members.find(m=>m.id===state?.session?.id);
const owner=()=>!!room()&&room().ownerId===state?.session?.id;
function recordKey(record){return record.gameId&&record.playerId&&record.playerId!=='legacy'?JSON.stringify([record.gameId,record.playerId]):JSON.stringify([record.gameId||'legacy-game','legacy',record.finishedAt||record.date||'',record.character||'',Boolean(record.won),Number(record.score)||0]);}
function mergeRecords(...groups){
  const records=new Map();
  for(const group of groups)for(const record of Array.isArray(group)?group:[]){
    if(!record||typeof record.mode!=='string')continue;
    const normalized={...record,playerId:record.playerId||'legacy',playerName:record.playerName||'历史身份',finishedAt:record.finishedAt||null};
    records.set(recordKey(normalized),normalized);
  }
  return [...records.values()].sort((a,b)=>(Date.parse(b.finishedAt)||0)-(Date.parse(a.finishedAt)||0)).slice(0,30);
}
function save(){
  const pendingRecords=[...prefs.records];
  const persist=()=>{try{const latest=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')||{};prefs.records=mergeRecords(latest.records,pendingRecords,prefs.records);localStorage.setItem(STORAGE_KEY,JSON.stringify(prefs));}catch{}};
  if(navigator.locks?.request)navigator.locks.request(STORAGE_KEY+'-write',persist).catch(persist);else persist();
}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function sound(frequency=500){if(!prefs.sound||!prefs.volume)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=frequency;g.gain.setValueAtTime(.12*prefs.volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.1);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.1);}catch{}}
function attributes(c){return `<div class="attribute-bars">${[['糖泡',c.capacity,c.maxCapacity],['威力',c.range,c.maxRange],['速度',c.speed,c.maxSpeed]].map(([name,n,max])=>`<div class="attribute"><span>${name}</span><span class="bar"><i style="width:${n/max*100}%"></i></span><b>${n}<small> / ${max}</small></b></div>`).join('')}</div>`;}
function frame(content){return `<div class="game-shell ${view==='battle'?'playing':''}"><header class="titlebar"><div class="game-brand"><span><h1>${GAME_NAME}</h1><small>${GAME_TAGLINE}</small></span></div><span class="edition-tag">开发测试版</span><div class="top-status"><button class="connection ${connected?'online':'offline'}" data-action="reconnect" title="重新连接本地服务">${connected?'本地服务已连接':'连接恢复中 · 点此重连'}</button><span class="top-user"><span class="avatar">${sprite(char(state.session.character).sprite)}</span><strong class="nickname">${esc(state.session.name)}</strong></span><button class="icon-btn" data-action="sound" aria-label="${prefs.sound?'关闭':'开启'}音效">${ico('sound')}</button><button class="icon-btn" data-action="settings" aria-label="系统设置">${ico('settings')}</button></div></header><nav class="main-nav" aria-label="游戏导航">${[['lobby','rooms','频道大厅'],['characters','person','角色资料'],['shop','shop','商城试穿'],['records','trophy','对战记录']].map(([id,i,n])=>`<button class="nav-tab ${view===id||id==='lobby'&&['room','battle','channels'].includes(view)?'active':''}" data-action="nav" data-view="${id}" ${view===id?'aria-current="page"':''}>${ico(i)}${n}</button>`).join('')}<button class="nav-tab nav-help" data-action="rules">${ico('help')}游戏指南</button></nav><main class="content">${content}</main><footer class="app-footer"><span>${GAME_NAME} · ${GAME_TAGLINE}</span><span>自建本地服务 · 不连接腾讯服务器</span></footer></div>`;}
function loginPage(){return `<main class="login-screen"><div class="login-art"><span class="login-world-title">云游仙境 · 灵葫争锋</span><div class="login-quote"><h2>灵葫一放<br>妙趣开场</h2><p>踩准方寸，躲开泡泡。<br>和伙伴一起，在仙境里过招。</p></div></div><section class="login-panel panel"><h1 class="login-game-title"><img src="./assets/branding/linghu-wordmark-login-1024.png" alt="" aria-hidden="true"><span class="sr-only">${GAME_NAME}</span></h1><p class="subtitle">${GAME_TAGLINE}</p><div class="notice">非腾讯官方客户端；本地身份无需 QQ 密码。</div><form id="login-form"><div class="field"><label for="nickname">你的昵称</label><input id="nickname" maxlength="12" value="灵葫旅人" autocomplete="off" required></div><label class="field-label">选择初始角色</label><div class="login-characters">${CHARACTERS.map(c=>`<button type="button" class="portrait-choice ${draftCharacter===c.id?'selected':''}" data-action="draft-character" data-character="${c.id}" aria-pressed="${draftCharacter===c.id}">${sprite(c.sprite)}<strong>${c.name}</strong></button>`).join('')}</div><button class="btn primary large" type="submit" ${busy?'disabled':''}>${busy?'正在连接…':'进入仙境'} ${ico('next')}</button><p id="login-error" class="error-message" role="alert" hidden></p></form><p class="login-note">启动本地服务后可在多个浏览器标签页加入同一房间，人数依地图而定。陪练会明确标为 AI。</p></section></main>`;}
function channelsPage(){const rooms=state.rooms;return `<div class="page-heading"><div><p class="eyebrow">REGION & CHANNEL</p><h2>选择频道</h2><p>区域、频道、小区，回到熟悉的出发顺序。</p></div><span class="tag">本机开发大区</span></div><div class="channel-layout"><section class="announcement panel"><div class="panel-title"><h3>公告栏</h3><span>重制进度</span></div><div class="announcement-art"></div><div class="announcement-copy"><h3>糖泡再相逢</h3><p>房间人数依地图确定，红蓝组队、角色差异与同伴营救由本地服务运行。</p><p>普通竞技、比武、抢包山、热血足球、推箱子、合作探险拥有各自的规则。</p><div class="notice">历史原版存在多个版本。本轮数值和地图中未确认的部分在游戏指南中单独说明。</div></div></section><section class="channel-picker panel"><div class="panel-title"><h3>小区选择</h3><span class="connection online">本地服务</span></div><div class="region-strip">当前区域 <strong>本机开发大区</strong><small>本机练习频道</small></div><div class="channel-tabs">${[['free','自由频道'],['practice','练习频道']].map(([id,name])=>`<button class="filter ${channel===id?'active':''}" data-action="channel" data-channel="${id}" aria-pressed="${channel===id}">${name}</button>`).join('')}</div><div class="district-grid">${[1,2,3].map(n=>{const id=n===1?channel:channel+'-'+n;return `<button class="district-card" data-action="district" data-channel="${id}"><span class="signal">▂▄▆</span><span><h3>${channel.startsWith('practice')?'练习':'自由'}小区 ${String(n).padStart(2,'0')}</h3><p>${rooms.filter(r=>r.channel===id).length} 个实际房间</p></span>${ico('next')}</button>`;}).join('')}</div><div class="channel-footer"><button class="btn secondary" data-action="logout">切换本地身份</button><button class="btn primary" data-action="district" data-channel="${channel}">进入大厅 ${ico('next')}</button></div></section></div>`;}
function roomCard(r){const waiting=r.status==='waiting',info=mapInfo(r.map,r.mapInfo),limit=maxSeats(r);return `<article class="room-card"><span class="room-number">${esc(String(r.id).slice(-3).toUpperCase())}</span><span class="room-mode">${esc(mode(r.mode).name)}</span><div class="room-copy"><h3>${esc(r.name)}</h3><p>${esc(mapName(r.map,r.mapInfo))} · ${r.count}/${limit} 席 · ${r.botCount} 位 AI</p><small>${mapDimensions(info)}${info?.kind==='draft-map'?' · 自定义技术试稿':''}</small></div><div class="seat-dots" aria-label="${r.count}个已用席位，地图最多${limit}席">${Array.from({length:limit},(_,i)=>`<i class="${i<r.count?i%2?'blue':'red':'empty'}"></i>`).join('')}</div><div class="room-actions"><span class="tag">${waiting?'等待加入':r.status==='finished'?'刚刚结束':'对局中'}</span><button class="btn secondary" data-action="join" data-room="${esc(r.id)}" ${waiting?'':'disabled'}>进入房间 ${ico('next')}</button></div></article>`;}
function profilePanel(){const c=char(state.session.character);return `<aside class="profile-panel panel"><div class="panel-title"><h3>我的角色</h3><span class="tag">本地身份</span></div><div class="profile-stage cosmetic-${esc(prefs.skin)}">${sprite(c.sprite)}</div><div class="profile-info"><h3>${esc(state.session.name)}</h3><span>${c.name}</span></div>${attributes(c)}<div class="profile-actions"><button class="btn secondary" data-action="nav" data-view="characters">更换角色</button><button class="btn ghost" data-action="nav" data-view="shop">试穿外观</button></div><div class="quick-tips"><h4>糖泡小贴士</h4><p>糖泡约 5 秒后炸出糖浆。被困时靠近队友，敌方接触会让你离场。</p><button class="text-btn" data-action="rules">查看各模式玩法 ${ico('next')}</button></div></aside>`;}
function lobbyPage(){const all=state.rooms.filter(r=>r.channel===channel),visible=all.filter(r=>modeFilter==='all'||r.mode===modeFilter);return `<div class="page-heading"><div><p class="eyebrow">LOBBY · LOCAL DISTRICT</p><h2>游戏大厅</h2><p>本机开发大区 <span class="crumb">›</span> ${channel.startsWith('practice')?'练习':'自由'}频道 <span class="crumb">›</span> 本地小区</p></div><div class="toolbar"><button class="btn secondary" data-action="nav" data-view="channels">${ico('back')}返回频道</button><button class="btn primary" data-action="create">${ico('plus')}创建房间</button></div></div><div class="lobby-layout"><section class="room-browser panel"><div class="panel-title"><h3>房间列表</h3><span class="room-count">${all.length} 个实际房间</span></div><div class="mode-tabs"><button class="filter ${modeFilter==='all'?'active':''}" data-action="filter" data-mode="all">全部</button>${MODES.map(m=>`<button class="filter ${modeFilter===m.id?'active':''}" data-action="filter" data-mode="${m.id}">${m.name}</button>`).join('')}</div><div class="room-cards">${visible.length?visible.map(roomCard).join(''):'<div class="empty-state"><span>☁</span><h3>这里还没有房间</h3><p>创建房间，邀请其他标签页的玩家加入，或添加 AI 陪练。</p><button class="btn primary" data-action="create">创建房间</button></div>'}</div><div class="lobby-message"><strong>系统</strong><p>欢迎来到${GAME_NAME}。房间、席位、聊天和对战来自当前本地服务。AI 与浏览器玩家分别标识。</p></div></section>${profilePanel()}</div>`;}
function seat(member,index){const r=room(),limit=maxSeats(r),locked=r.lockedSeats.includes(index),self=member?.id===state.session.id;if(index>=limit)return `<div class="seat empty locked" aria-label="${index+1}号席位，此地图不适用"><div class="seat-top"><span>${index+1} 号席位</span><span>不适用</span></div><div class="seat-art" aria-hidden="true">—</div><h3 class="seat-name">此图不适用</h3><span class="seat-meta">本地图最多 ${limit} 人</span></div>`;if(!member)return `<div class="seat empty ${locked?'locked':''}"><div class="seat-top"><span>${index+1} 号席位</span><span>${locked?'已关闭':'空闲'}</span></div><div class="seat-art">${ico(locked?'close':'plus')}</div><h3 class="seat-name">${locked?'暂不开放':'等待玩家'}</h3>${owner()?`<button class="seat-control text-btn" data-action="seat" data-seat="${index}" data-locked="${!locked}">${locked?'开放席位':'关闭席位'}</button>`:'<span class="seat-meta">可从大厅加入</span>'}</div>`;const c=char(member.character);return `<div class="seat ${member.team} ${self?'self':''}"><div class="seat-top"><span>${index+1} 号席位 ${self?'· 你':''}</span><span class="tag">${member.id===r.ownerId?'房主':member.isBot?'AI 陪练':member.ready?'已准备':'未准备'}</span></div><div class="seat-art ${self?'cosmetic-'+esc(prefs.skin):''}">${sprite(c.sprite)}</div><h3 class="seat-name">${esc(playerName(member))}</h3><span class="seat-meta">${c.name} · ${member.team==='red'?'红队':'蓝队'}</span></div>`;}
function chatLines(){return room().chat.length?room().chat.map(m=>`<div class="chat-line"><strong>${esc(m.name)}：</strong><span>${esc(m.text)}</span></div>`).join(''):'<p class="muted">系统：欢迎进入房间。聊天仅发送到当前本地房间。</p>';}
function chatPanel(){return `<section class="room-chat"><div class="chat-messages" role="log" aria-label="房间聊天">${chatLines()}</div><form class="chat-form" id="chat-form"><label class="sr-only" for="chat-input">房间聊天内容</label><input id="chat-input" maxlength="200" placeholder="说点什么吧…（仅当前房间）" autocomplete="off"><button class="btn secondary" type="submit">发送</button></form></section>`;}
function roomPage(){const r=room(),self=me(),botCount=r.members.filter(p=>p.isBot).length,limit=maxSeats(r),info=mapInfo(r.map,r.mapInfo);return `<div class="page-heading"><div><p class="eyebrow">ROOM · ${esc(String(r.id).slice(-5).toUpperCase())}</p><h2>${esc(r.name)}</h2><p>${mode(r.mode).name} · ${r.members.length}/${limit} 席 · ${r.members.filter(m=>!m.isBot).length} 位浏览器玩家</p></div><div class="toolbar"><button class="btn secondary" data-action="leave">${ico('back')}返回大厅</button>${owner()?'<button class="btn secondary" data-action="config">房间属性</button>':''}</div></div><div class="room-layout"><section class="room-stage panel"><div class="panel-title"><h3>队伍席位</h3><span>${mapDimensions(info)} · 此图最多 ${limit} 人</span></div><div class="seat-grid">${Array.from({length:8},(_,i)=>seat(r.members.find(p=>p.seat===i),i)).join('')}</div><div class="team-strip"><span>我的队伍</span><button class="btn ${self?.team==='red'?'primary':'secondary'} red-choice" data-action="team" data-team="red" ${r.mode==='adventure'?'disabled':''}>红队</button><button class="btn ${self?.team==='blue'?'primary':'secondary'} blue-choice" data-action="team" data-team="blue" ${r.mode==='adventure'?'disabled':''}>蓝队</button><button class="btn ghost" data-action="choose">更换角色</button>${owner()?`<button class="btn secondary" data-action="add-bot" ${r.members.length>=limit?'disabled':''}>${ico('plus')}添加 AI</button>${botCount?'<button class="btn ghost" data-action="remove-bot">移除 AI</button>':''}`:''}</div>${chatPanel()}</section><aside class="room-control panel"><div class="panel-title"><h3>本局设置</h3><span class="tag">${owner()?'你是房主':'玩家'}</span></div><p class="art-work-status" id="map-art-status" role="status"></p><div class="map-preview"><canvas id="map-preview" width="480" height="416" aria-label="${esc(mapName(r.map,r.mapInfo))}，${mapDimensions(info)}，地图预览"></canvas><span>${esc(mapName(r.map,r.mapInfo))}</span></div><p id="map-preview-status" class="muted" role="status">正在载入地图…</p><dl class="room-facts"><dt>模式</dt><dd>${mode(r.mode).name}</dd><dt>时长</dt><dd>${r.duration/60} 分钟</dd><dt>组队</dt><dd>${r.mode==='adventure'?'合作闯关':'红蓝对抗'}</dd><dt>地图规格</dt><dd>${mapDimensions(info)}</dd><dt>地图来源</dt><dd>${sourceKind(info)?'源数据候选':'自定义技术试稿'}</dd></dl><p class="mode-description">${mode(r.mode).description}</p><button class="text-btn" data-action="map-info" data-map="${esc(r.map)}">地图核对状态</button><div class="room-button-stack">${owner()?`<button class="btn primary large" data-action="start">${ico('play')}开始游戏</button>`:`<button class="btn ${self?.ready?'secondary':'primary'} large" data-action="ready" data-ready="${!self?.ready}">${ico('check')}${self?.ready?'取消准备':'准备'}</button>`}</div><p class="ready-note">${owner()?'其他真人准备后，房主可开始游戏。AI 自动准备。':'准备后等待房主开局。'}<br>方向键移动 · 空格操作</p></aside></div>`;}
function battlePage(){const r=room(),g=r.game;return `<div class="match-heading"><div><p class="eyebrow">${mode(g.mode).name} · ${esc(mapName(r.map,r.mapInfo))} · ${g.width}列 × ${g.height}行</p><h2>${g.mode==='adventure'?'并肩探险':'糖泡对决'}</h2></div><div class="scoreboard"><span class="team-score red">红队 <b id="red-score">0</b></span><span class="match-clock" id="clock">${clock(r.duration)}</span><span class="team-score blue">${g.mode==='adventure'?'关卡':'蓝队'} <b id="blue-score">0</b></span></div><div class="match-actions">${owner()?`<button class="btn secondary" data-action="pause">${ico('pause')}暂停</button>`:''}<button class="btn secondary" data-action="leave-confirm">离开</button></div></div><div class="battle-layout"><section class="arena-panel panel"><div class="arena-caption"><span>☯ ${esc(r.name)}</span><span id="match-state" aria-live="polite">对局进行中</span></div><p class="art-work-status" id="arena-art-status" role="status"></p><canvas id="arena" width="960" height="832" tabindex="0" aria-label="${g.width}列${g.height}行糖泡对战棋盘。方向键移动，空格操作，1使用针道具。"></canvas><div class="battle-hint"><span><kbd>↑ ↓ ← →</kbd> 移动</span><span><kbd>空格</kbd> 放泡 / 踢泡 / 推箱</span><span><kbd>1</kbd> 使用针道具</span></div></section><aside class="battle-panel panel"><div class="panel-title"><h3>对局成员</h3><span id="alive-count"></span></div><div id="battle-roster"></div><div class="my-stats" id="my-stats"></div><div class="event-feed"><h4>对局动态</h4><div id="event-list" role="log"></div></div><p class="mode-description">${mode(g.mode).description}</p><button class="btn secondary" data-action="rules">查看玩法</button></aside></div><div class="touch-controls" aria-label="触屏控制"><div class="dpad"><button data-dir="0,-1" aria-label="向上">↑</button><button data-dir="-1,0" aria-label="向左">←</button><button data-dir="0,1" aria-label="向下">↓</button><button data-dir="1,0" aria-label="向右">→</button></div><div class="touch-actions"><button class="btn secondary" data-action="item">道具 1</button><button class="btn primary large" data-action="bomb">${g.mode==='soccer'?'踢糖泡':g.mode==='push'?'推射箱子':'放糖泡'}</button></div></div>`;}
function charactersPage(){return `<div class="page-heading"><div><p class="eyebrow">CHARACTER SELECT</p><h2>角色资料</h2><p>采用自有的道童、月影、山岳与莲花身份，外观与玩法属性分开映射。</p></div></div><div class="character-grid">${CHARACTERS.map(c=>`<button class="character-card ${c.id===state.session.character?'selected':''}" data-action="character" data-character="${c.id}" aria-pressed="${c.id===state.session.character}"><div class="character-art cosmetic-${esc(prefs.skin)}">${sprite(c.sprite)}</div><div class="character-copy"><span class="tag">${c.id===state.session.character?'当前角色':'自有道家角色'}</span><h3>${c.name}</h3><p>${c.description}</p>${attributes(c)}<span class="btn ${c.id===state.session.character?'primary':'secondary'}">${c.id===state.session.character?'已选择':'选择角色'}</span></div></button>`).join('')}</div><p class="notice">四位自有角色沿用当前四个玩法属性槽位；本轮仅替换人物美术和身份，不改变数值。</p>`;}
function shopPage(){const c=char(state.session.character);return `<div class="page-heading"><div><p class="eyebrow">WARDROBE PREVIEW</p><h2>商城 · 本地试穿</h2><p>本轮提供外观试穿与本机保存，无 Q币支付、商城服务或属性加成。</p></div></div><div class="wardrobe-layout"><section class="wardrobe-preview panel cosmetic-${esc(prefs.skin)}">${sprite(c.sprite)}<h3>${c.name}</h3><p>${cosmetics.find(s=>s.id===prefs.skin).name}</p></section><section class="wardrobe-items">${cosmetics.map(c=>`<button class="cosmetic-card panel ${prefs.skin===c.id?'selected':''}" data-action="skin" data-skin="${c.id}"><span class="cosmetic-swatch ${c.id}">☯</span><h3>${c.name}</h3><p>${c.desc}</p><span class="btn ${prefs.skin===c.id?'primary':'secondary'}">${prefs.skin===c.id?'使用中':'免费试穿'}</span></button>`).join('')}<p class="notice">这是重制版扩展的显示滤镜，没有把原版收费商城或购买回执标记为已接入。</p></section></div>`;}
function recordsPage(){const records=prefs.records;return `<div class="page-heading"><div><p class="eyebrow">LOCAL MATCH HISTORY</p><h2>对战记录</h2><p>记录当前浏览器各本地身份的真实对局；同局不同玩家分别记录，不计入腾讯原账号。</p></div></div><div class="record-summary"><div class="stat"><small>对局场次</small><strong>${records.length}</strong></div><div class="stat"><small>获胜场次</small><strong>${records.filter(r=>r.won).length}</strong></div><div class="stat"><small>累计表现分</small><strong>${records.reduce((a,r)=>a+(Number(r.score)||0),0)}</strong></div></div><section class="record-list panel">${records.length?records.map(r=>`<div class="record-row"><span class="result-mark ${r.won?'won':''}">${r.won?'胜':r.draw?'平':'负'}</span><div><h3>${esc(r.mode)}</h3><small>${esc(r.date)}</small></div><span>${esc(r.playerName||'历史身份')} · ${esc(characterDisplayName(r.character))}</span><span>${Number(r.score)||0} 分</span><span>${clock(Number(r.elapsed)||0)}</span></div>`).join(''):'<div class="empty-state"><span>♜</span><h3>下一局，写下你的故事</h3><p>前往大厅加入房间，结算后会自动保存记录。</p></div>'}</section>`;}
function render(){if(view==='login'){app.innerHTML=loginPage();return;}const active=document.activeElement,chatDraft=active?.id==='chat-input'?{value:active.value,start:active.selectionStart,end:active.selectionEnd}:null;app.innerHTML=frame(({channels:channelsPage,lobby:lobbyPage,room:roomPage,battle:battlePage,characters:charactersPage,shop:shopPage,records:recordsPage}[view]||lobbyPage)());lastChat='';if(view==='room'){drawPreview();updateChat();if(chatDraft&&$('#chat-input')){const input=$('#chat-input');input.value=chatDraft.value;input.focus({preventScroll:true});input.setSelectionRange(chatDraft.start,chatDraft.end);}}if(view==='battle')updateBattle();}
function accept(snapshot){
  if(!snapshot?.session)return;
  state=snapshot;connected=true;const r=room(),had=lastRoomId;lastRoomId=r?.id||null;
  if(['result','paused'].includes(modal)&&(!r?.game||r.game.id!==modalGameId||(modal==='result'&&r.game.status!=='finished')||(modal==='paused'&&!r.paused)))closeModal();
  if(r){if(r.game)view='battle';else if(!['characters','shop','records'].includes(view)||had!==r.id)view='room';}else if(['room','battle','login'].includes(view))view='lobby';
  const fingerprint=JSON.stringify([view,state.session,state.rooms,r?{id:r.id,name:r.name,mode:r.mode,map:r.map,duration:r.duration,ownerId:r.ownerId,members:r.members,lockedSeats:r.lockedSeats,paused:r.paused,game:r.game?{id:r.game.id,status:r.game.status}:null}:null]);
  if(fingerprint!==lastFingerprint){lastFingerprint=fingerprint;render();}else if(view==='battle')updateBattle();
  if(view==='room')updateChat();
  if(r?.game?.status==='finished'&&!finishSeen.has(r.game.id)){finishSeen.add(r.game.id);showResult(r.game);}
  if(r?.game&&r.paused&&modal!=='paused'&&!modal)showPaused();
}
function setConnection(value){connected=value;const el=$('.top-status .connection');if(el){el.className='connection '+(value?'online':'offline');el.textContent=value?'本地服务已连接':'连接恢复中 · 点此重连';}}
function showModal(title,body,actions='',kind='generic'){lastFocus=document.activeElement;modal=kind;modalGameId=['result','paused'].includes(kind)?room()?.game?.id||null:null;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2>${kind==='paused'?'':`<button class="icon-btn" data-action="close-modal" aria-label="关闭弹窗">${ico('close')}</button>`}</div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;app.inert=true;document.body.classList.add('modal-open');pressed.clear();held=null;requestAnimationFrame(()=>($('#modal-root input')||$('#modal-root button'))?.focus());}
function closeModal(){modal='';modalGameId=null;modalRoot.innerHTML='';app.inert=false;document.body.classList.remove('modal-open');if(lastFocus?.isConnected)lastFocus.focus();pressed.clear();held=null;}
function showPaused(){showModal('对局已暂停','<p>房主已暂停，计时和对局状态均已冻结。</p>',owner()?'<button class="btn primary" data-action="resume">继续游戏</button>':'<p class="muted">等待房主继续。</p>','paused');}
function rules(){showModal(`${GAME_NAME} · 游戏指南`,`<div class="rules-list">${MODES.map(m=>`<article><h3>${m.name}</h3><p>${m.description}</p></article>`).join('')}</div><div class="notice"><strong>基础操作：</strong>方向键移动，空格放糖泡；热血足球用空格踢糖泡，推箱子用方向配合空格推射。被困后队友相邻接触营救、敌方接触淘汰，糖泡和困泡候选基准均为5秒。只有拾取针后才能按1自救。WASD和触屏为重制版扩展。</div><p class="muted">本轮为自建客户端／本地权威服务，不接原腾讯账号或协议。地图名称、行列与人数以实际目录为准，源数据候选尚待核实腾讯原始版本；自定义技术试稿不代表原版地图。三波探险、比武10分及速度换算仍为重制约定。英雄传说、机械、寻宝等其余模式与完整原版关卡尚未复原。商城为本地试穿。</p>`, '<button class="btn primary" data-action="close-modal">了解了</button>','rules');}
function configForm(create){
  const r=create?{name:'中国城01练习房',mode:'classic',map:'source-201',duration:180,members:[]}:room();
  const info=mapInfo(r.map),humans=create?1:r.members.filter(m=>!m.isBot).length,limit=Number(info?.maxSeats)||4,maxBots=Math.max(0,limit-humans),bots=Math.min(maxBots,create?3:r.members.filter(m=>m.isBot).length);
  const modeAllowed=id=>!!info?.playableModes?.includes(id);
  const option=m=>`<option value="${esc(m.id)}" ${m.id===r.map?'selected':''} ${canPreviewMap(m)?'':'disabled'} title="${esc(canPreviewMap(m)?'':unavailableMapReason(m))}">${esc(m.name)} · ${mapDimensions(m)} · ${m.maxSeats}人${canPreviewMap(m)?'':' · '+esc(unavailableMapReason(m))}</option>`;
  return `<form id="config-form" data-create="${create}" data-human-count="${humans}"><div class="field"><label for="room-name">房间名称</label><input id="room-name" maxlength="16" value="${esc(r.name)}" required></div><div class="config-grid"><div class="field"><label for="room-mode">游戏模式</label><select id="room-mode">${MODES.map(m=>`<option value="${m.id}" ${m.id===r.mode?'selected':''} ${modeAllowed(m.id)?'':'disabled'}>${m.name}${modeAllowed(m.id)?'':' · 此图暂不可用'}</option>`).join('')}</select></div><div class="field"><label for="room-map">选择地图（${mapDirectory.maps.length}条目录）</label><select id="room-map" aria-describedby="map-choice-note" ${mapDirectoryStatus==='ready'?'':'disabled'}><optgroup label="社区源地图 · 来源待核对">${mapDirectory.maps.map(option).join('')}</optgroup><optgroup label="自定义技术试稿 · 非原版地图">${mapDirectory.draftMaps.map(option).join('')}</optgroup></select></div><div class="field"><label for="room-bots">AI 席位</label><select id="room-bots">${Array.from({length:maxBots+1},(_,i)=>`<option value="${i}" ${i===bots?'selected':''}>${i} 位 AI</option>`).join('')}</select></div><div class="field"><label for="room-duration">时长</label><select id="room-duration">${[60,120,180,300].map(n=>`<option value="${n}" ${n===r.duration?'selected':''}>${n/60} 分钟</option>`).join('')}</select></div></div><p id="map-choice-note" class="notice" role="status">${configMapNote(info,humans)}</p><details><summary>地图来源与核对状态</summary><p>源数据候选取自留存的社区客户端文件，尚未确认腾讯原始版本和完整像素碰撞。试稿地图只用于功能测试。</p><a href="./docs/SOURCE_MAP_RUNTIME_INTERFACE.md" target="_blank" rel="noopener">查看详细核对记录</a></details><p class="muted">人数和可用模式随地图确定；灰色地图尚不能开始。AI会明确标示。</p><div class="modal-actions"><button type="button" class="btn secondary" data-action="close-modal">取消</button><button type="submit" class="btn primary" ${canPreviewMap(info)?'':'disabled'}>${create?'创建并进入':'保存设置'}</button></div></form>`;
}
function configMapNote(info,humans){return info?`${esc(info.name)} · ${mapDimensions(info)} · 最多 ${info.maxSeats} 人。${sourceKind(info)?'源数据候选，腾讯原始版本与完整碰撞仍待核对。':'自定义技术试稿，不是原版地图。'}${humans>info.maxSeats?'当前真人数超过此图上限，请先调整房间成员。':''}`:mapDirectoryStatus==='error'?'地图目录未能载入：'+esc(mapDirectoryError):'正在载入地图目录…';}
function syncConfigMap(){
  const form=$('#config-form');if(!form)return;const info=mapInfo($('#room-map').value),humans=Number(form.dataset.humanCount)||1,bots=$('#room-bots'),previous=Number(bots.value),limit=Math.max(0,(info?.maxSeats||0)-humans);
  bots.innerHTML=Array.from({length:limit+1},(_,i)=>`<option value="${i}" ${i===Math.min(previous,limit)?'selected':''}>${i} 位 AI</option>`).join('');
  const modes=$('#room-mode');for(const option of modes.options)option.disabled=!info?.playableModes?.includes(option.value);if(modes.selectedOptions[0]?.disabled)modes.value=info?.playableModes?.[0]||'';
  $('#map-choice-note').innerHTML=configMapNote(info,humans);
  form.querySelector('button[type="submit"]').disabled=!canPreviewMap(info)||humans>info.maxSeats;
}
function choose(){showModal('选择角色',`<div class="login-characters">${CHARACTERS.map(c=>`<button class="portrait-choice ${state.session.character===c.id?'selected':''}" data-action="choose-character" data-character="${c.id}">${sprite(c.sprite)}<strong>${c.name}</strong></button>`).join('')}</div><p class="muted">糖泡、威力和速度因角色而异。</p>`,'','choose');}
function settings(){showModal('系统设置',`<div class="setting-row"><span>游戏音效</span><button class="btn secondary" data-action="modal-sound">${prefs.sound?'已开启':'已关闭'}</button></div><div class="field"><label for="volume">音量 <b id="volume-label">${Math.round(prefs.volume*100)}%</b></label><input type="range" id="volume" min="0" max="100" value="${prefs.volume*100}"></div><p class="notice">游戏状态由本地服务判定，切换标签页不会暂停其他玩家。房主可主动暂停整局；失焦仅释放自己的移动按键。</p>`,'<button class="btn primary" data-action="close-modal">完成设置</button>','settings');}
function showResult(g){const p=g.players.find(p=>p.id===state.session.id);if(!p)return;const won=g.winnerTeam===p.team,draw=g.winnerTeam==='draw';if(!prefs.records.some(record=>record.gameId===g.id&&record.playerId===p.id))prefs.records.unshift({gameId:g.id,playerId:p.id,playerName:p.name,finishedAt:new Date().toISOString(),mode:mode(g.mode).name,character:char(p.character).name,won,draw,score:p.score,elapsed:Math.round(g.time/1000),date:new Date().toLocaleString('zh-CN')});prefs.records=prefs.records.slice(0,30);save();showModal('本局结算',`<div class="result-banner ${won?'won':''}"><span>${won?'胜利':draw?'平局':'再接再厉'}</span><h3>${mode(g.mode).name}</h3><p>${esc(endReasonText(g.endReason))} · ${clock(g.time/1000)}</p></div><table class="result-table"><thead><tr><th>玩家</th><th>队伍</th><th>表现分</th></tr></thead><tbody>${[...g.players].sort((a,b)=>b.score-a.score).map(p=>`<tr><td>${esc(playerName(p))}${p.id===state.session.id?' · 你':''}</td><td>${p.team==='red'?'红队':'蓝队'}</td><td>${p.score}</td></tr>`).join('')}</tbody></table><p class="muted">成绩来自本次本地权威服务，不向腾讯原账号写入。</p>`,'<button class="btn secondary" data-action="leave">返回大厅</button><button class="btn primary" data-action="return-room">返回房间</button>','result');sound(won?850:380);}
function updateChat(){const el=$('.chat-messages');if(!el||!room())return;const signature=JSON.stringify(room().chat);if(signature!==lastChat){el.innerHTML=chatLines();el.scrollTop=el.scrollHeight;lastChat=signature;}}
function updateBattle(){const g=room()?.game;if(!g||!$('#arena'))return;const self=g.players.find(p=>p.id===state.session.id);$('#clock').textContent=clock(g.duration-g.time/1000);$('#red-score').textContent=g.scores.red;$('#blue-score').textContent=g.mode==='adventure'?`${g.wave}/${g.totalWaves}`:g.scores.blue;$('#alive-count').textContent=`${g.players.filter(p=>p.alive).length} 人在场`;$('#battle-roster').innerHTML=g.players.map(p=>`<div class="battle-player ${p.team} ${p.alive?'':'out'}"><span class="avatar">${sprite(char(p.character).sprite)}</span><span class="player-copy"><strong>${esc(playerName(p))}${p.id===state.session.id?' · 你':''}</strong><small>${char(p.character).name} · ${p.score}分</small></span><span class="player-status">${p.trappedUntil?'被困':!p.alive?p.respawnAt?'待复活':'离场':p.carrying?'携包':'在场'}</span></div>`).join('');$('#my-stats').innerHTML=self?[['糖泡',self.capacity],['威力',self.range],['速度',self.speed],['针',self.inventory?.needle||0],...(g.mode==='push'||g.mode==='adventure'?[['生命',self.hp]]:[])].map(([n,v])=>`<div class="stat"><small>${n}</small><strong>${v}</strong></div>`).join(''):'';$('#event-list').textContent=g.events.slice(-3).map(e=>e.text).join(' · ');const status=room().paused?'全房暂停':self?.trappedUntil?'被困中：等待队友接触营救，或有针时按1':!self?.alive?self?.respawnAt?'等待复活':'你已离场，正在观战':self?.carrying?'携带包子，返回本方基地！':'对局进行中';if($('#match-state').textContent!==status)$('#match-state').textContent=status;}
const actorPaintState=new WeakMap();
function paintBoard(canvas,g,preview=false){
  if(!canvas)return;
  const ctx=canvas.getContext('2d'),cell=g.sourceMap?40:64,unit=cell/64,now=performance.now(),density=2;
  const logicalWidth=g.width*cell,logicalHeight=g.height*cell;
  if(canvas.width!==logicalWidth*density)canvas.width=logicalWidth*density;
  if(canvas.height!==logicalHeight*density)canvas.height=logicalHeight*density;
  ctx.setTransform(density,0,0,density,0,0);
  canvas.dataset.logicalWidth=logicalWidth;canvas.dataset.logicalHeight=logicalHeight;canvas.dataset.renderDensity=density;
  canvas.style.setProperty('--map-ratio',g.width/g.height);
  ctx.clearRect(0,0,logicalWidth,logicalHeight);ctx.fillStyle='#e5e9d6';ctx.fillRect(0,0,logicalWidth,logicalHeight);
  let history=actorPaintState.get(canvas);
  if(!history||history.gameId!==g.id){history={gameId:g.id,players:new Map()};actorPaintState.set(canvas,history);}
  const drawScaled=draw=>{ctx.save();ctx.scale(unit,unit);draw();ctx.restore();};
  const drawGroundEffects=()=>drawScaled(()=>{
    if(g.mode==='bun')for(const team of ['red','blue']){
      const b=g.objectives[team];if(!b)continue;
      ctx.fillStyle=team==='red'?'#c7655c66':'#5a8fc166';ctx.fillRect(b.x*64-5,b.y*64-5,74,74);
      drawSprite(ctx,5,b.x*64-8,b.y*64-10,80,80);ctx.fillStyle='#335749';ctx.font='bold 20px Microsoft YaHei';ctx.textAlign='center';ctx.fillText(String(b.buns),b.x*64+32,b.y*64+55);
    }
    for(const p of g.pickups){if(p.availableAt>g.time)continue;
      if(p.type==='bun')drawSprite(ctx,5,p.x*64,p.y*64,64,64);
      else if(p.type==='needle'){ctx.strokeStyle='#1d7669';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(p.x*64+20,p.y*64+48);ctx.lineTo(p.x*64+45,p.y*64+15);ctx.stroke();ctx.fillStyle='#fcf8d6';ctx.beginPath();ctx.arc(p.x*64+44,p.y*64+16,5,0,Math.PI*2);ctx.fill();}
      else drawSprite(ctx,7,p.x*64+5,p.y*64+5,54,54,'tiles');
    }
    for(const b of g.blasts){const grad=ctx.createRadialGradient(b.x*64+32,b.y*64+32,3,b.x*64+32,b.y*64+32,42);grad.addColorStop(0,'#fff9dfee');grad.addColorStop(.4,'#f7bb4fcc');grad.addColorStop(1,'#f6ca5c00');ctx.fillStyle=grad;ctx.fillRect(b.x*64-10,b.y*64-10,84,84);}
  });
  const entities=[];
  for(const b of g.bombs)entities.push({sortY:(b.y+.8)*cell,draw:()=>{
    drawSprite(ctx,3,b.x*64-5,b.y*64-5,74,74,'tiles');
    if(!preview){ctx.fillStyle='#165e58';ctx.font='bold 16px sans-serif';ctx.textAlign='center';ctx.fillText(Math.max(.1,(b.explodeAt-g.time)/1000).toFixed(1),b.x*64+32,b.y*64+52);}
  }});
  for(const m of g.monsters)if(m.alive)entities.push({sortY:(m.y+.8)*cell,draw:()=>{
    drawSprite(ctx,4,m.x*64-10,m.y*64-20,84,84);ctx.fillStyle='#ae5565';ctx.fillRect(m.x*64+6,m.y*64-7,52*m.hp/m.maxHp,4);
    if(m.boss){ctx.fillStyle='#8c455a';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.fillText('BOSS',m.x*64+32,m.y*64-12);}
  }});
  for(const p of g.players)if(p.alive){
    let motion=history.players.get(p.id);
    if(!motion){motion={x:p.x,y:p.y,lastMove:-Infinity,start:now};history.players.set(p.id,motion);}
    if(motion.x!==p.x||motion.y!==p.y){if(now-motion.lastMove>220)motion.start=now;motion.x=p.x;motion.y=p.y;motion.lastMove=now;}
    entities.push({sortY:(p.y+.8)*cell,draw:()=>{
      ctx.fillStyle=p.team==='red'?'#d77972':'#659ac1';ctx.beginPath();ctx.ellipse(p.x*64+32,p.y*64+51,22,8,0,0,Math.PI*2);ctx.fill();
      const animated=!preview&&!p.trappedUntil&&now-motion.lastMove<190&&drawCharacterMotion(ctx,p.character,p.x*64+32,p.y*64+59,110,{action:'run',direction:p.facing,elapsedMs:now-motion.start,allowCandidate:true});
      if(!animated)drawSprite(ctx,char(p.character).sprite,p.x*64-9,p.y*64-27,82,90);
      if(p.trappedUntil){ctx.fillStyle='#94dbed70';ctx.strokeStyle='#f2ffff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x*64+32,p.y*64+26,33,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#20556a';ctx.textAlign='center';ctx.font='bold 17px sans-serif';ctx.fillText(Math.max(0,(p.trappedUntil-g.time)/1000).toFixed(1),p.x*64+32,p.y*64+33);}
      if(p.carrying)drawSprite(ctx,5,p.x*64+31,p.y*64-16,35,35);
      if(p.id===state?.session?.id){ctx.fillStyle='#eece63';ctx.beginPath();ctx.moveTo(p.x*64+26,p.y*64-20);ctx.lineTo(p.x*64+38,p.y*64-20);ctx.lineTo(p.x*64+32,p.y*64-11);ctx.fill();}
    }});
  }
  entities.sort((a,b)=>a.sortY-b.sortY);let cursor=0,groundDrawn=false;
  const drawActorRows=boundary=>{if(!groundDrawn){drawGroundEffects();groundDrawn=true;}while(cursor<entities.length&&entities[cursor].sortY<boundary)drawScaled(entities[cursor++].draw);};
  if(g.sourceMap){
    const result=paintSourceMap(ctx,g.sourceMap,{drawActorRows});
    const status=result.failedFiles.length?`贴图读取失败（${result.failedFiles.length}张）`:result.notDecoded?`贴图载入中…`:result.missingElementIds.length?`美术待补 ${result.missingElementIds.length} 类元素`:'道家 Q 版场景制作稿';
    canvas.dataset.artStatus=status;canvas.dataset.missingArt=result.missingElementIds.join(',');canvas.setAttribute('aria-label',`${g.sourceMap.name}，${g.width}列${g.height}行。${status}${canvas.id==='arena'?'。方向键移动，空格放糖泡，1使用针。':''}`);
    const label=canvas.id==='arena'?$('#arena-art-status'):$('#map-art-status');if(label)label.textContent=status;
  }else{
    for(let y=0;y<g.height;y++)for(let x=0;x<g.width;x++){ctx.fillStyle=(x+y)%2?'#e7ecd9':'#f1f1de';ctx.fillRect(x*64,y*64,64,64);drawSprite(ctx,6,x*64-4,y*64-4,72,72,'tiles');if(g.grid[y][x])drawSprite(ctx,g.grid[y][x]===1?4:5,x*64-3,y*64-7,70,70,'tiles');}
    drawActorRows(Infinity);canvas.dataset.artStatus='自定义技术试稿';
  }
}
async function drawPreview(){
  const r=room(),canvas=$('#map-preview'),status=$('#map-preview-status');if(!r||!canvas)return;
  const roomId=r.id,mapId=r.map,info=mapInfo(mapId,r.mapInfo);
  const current=()=>view==='room'&&room()?.id===roomId&&room()?.map===mapId&&$('#map-preview')===canvas;
  if(status)status.textContent='正在载入'+mapName(mapId,r.mapInfo)+'…';
  try{
    if(sourceKind(info)||String(mapId).startsWith('source-')){
      const source=await loadSourceMap(mapId);if(!current())return;
      const artLoad=await prepareMapArt(source,{retry:true});if(!current())return;
      if(artLoad.failed)throw new Error(`该地图有${artLoad.failed}张贴图未能读取，请重试。`);
      const spawns=[...source.spawnGroups.A,...source.spawnGroups.B].filter((point,index,list)=>list.findIndex(p=>p.x===point.x&&p.y===point.y)===index);
      const players=r.members.map((member,index)=>({...member,...spawns[index],alive:true,trappedUntil:null}));
      if(players.some(p=>!Number.isInteger(p.x)||!Number.isInteger(p.y)))throw new Error('地图出生位置不足，预览已停止。');
      const preview={width:source.width,height:source.height,map:mapId,mapKind:'source-map',geometryStatus:source.geometryStatus,sourceMap:source,mode:r.mode,time:0,grid:source.grid,layers:source.layers,players,bombs:[],blasts:[],pickups:[],monsters:[],objectives:{red:null,blue:null},scores:{red:0,blue:0}};
      paintBoard(canvas,preview,true);if(status)status.textContent=`${source.name} · ${source.width}列 × ${source.height}行 · 最多${source.playerLimit}人 · 源数据候选`;
    }else{
      if(info?.kind!=='draft-map')throw new Error('未找到该地图，预览已停止。');
      paintBoard(canvas,createGame({mode:r.mode,map:mapId,seed:42,participants:r.members}),true);if(status)status.textContent='自定义技术试稿，仅供功能测试，不是原版地图。';
    }
  }catch(error){if(!current())return;canvas.getContext('2d')?.clearRect(0,0,canvas.width,canvas.height);if(status){status.textContent='地图预览未能载入：'+error.message+' ';const button=document.createElement('button');button.type='button';button.className='text-btn';button.dataset.action='retry-preview';button.textContent='重试预览';status.append(button);}}
}
function command(action,fields={}){return network.action(action,fields);}
async function act(action,el){switch(action){
  case'draft-character':{const nick=$('#nickname')?.value;draftCharacter=el.dataset.character;render();if(nick!==undefined)$('#nickname').value=nick;break;}
  case'nav':{const next=el.dataset.view;if(room()?.game&&next!=='battle'){showModal('离开当前对局？','<p>离开将退出当前房间，本局角色会由服务端处理。</p>','<button class="btn secondary" data-action="close-modal">继续游戏</button><button class="btn danger" data-action="leave">离开房间</button>','leave');break;}if(room()&&['lobby','channels'].includes(next))await command('leave');view=next;closeModal();render();break;}
  case'channel':channel=el.dataset.channel;render();break;
  case'district':channel=el.dataset.channel;view='lobby';render();break;
  case'filter':modeFilter=el.dataset.mode;render();break;
  case'create':if(room()){toast('请先离开当前房间。');break;}await loadMapDirectory();showModal('创建房间',configForm(true),'','config');break;
  case'config':await loadMapDirectory();showModal('房间属性',configForm(false),'','config');break;
  case'join':await network.join(el.dataset.room);view='room';render();break;
  case'seat':if(Number(el.dataset.seat)>=maxSeats(room()))break;await command('seat',{seat:Number(el.dataset.seat),locked:el.dataset.locked==='true'});break;
  case'add-bot':if(room().members.length>=maxSeats(room())){toast('此地图的席位已满。');break;}await command('config',{bots:room().members.filter(m=>m.isBot).length+1});break;
  case'remove-bot':await command('config',{bots:Math.max(0,room().members.filter(m=>m.isBot).length-1)});break;
  case'team':await command('team',{team:el.dataset.team});break;
  case'ready':await command('ready',{ready:el.dataset.ready==='true'});break;
  case'start':await command('start');view='battle';render();window.scrollTo(0,0);$('#arena')?.focus({preventScroll:true});break;
  case'choose':choose();break;
  case'character':case'choose-character':await command('character',{character:el.dataset.character});prefs.character=el.dataset.character;save();closeModal();render();break;
  case'bomb':{if(!connected){toast('正在恢复连接，请稍候。');break;}const data=await network.input({type:'bomb'});if(data.accepted)sound(360);else toast(room()?.mode==='soccer'?'身边没有可踢的糖泡。':room()?.mode==='push'?'面朝方向没有可操作的箱子。':'当前无法放置糖泡。');break;}
  case'item':{const data=await network.input({type:'item'});if(!data.accepted)toast('被困且持有针道具时才能自救。');break;}
  case'pause':await command('pause',{paused:true});break;
  case'resume':await command('pause',{paused:false});closeModal();break;
  case'return-room':if(room()?.game)await command('return');closeModal();view=room()?'room':'lobby';render();break;
  case'leave-confirm':showModal('离开当前对局？','<p>确定退出当前房间？其他玩家可继续对局。</p>','<button class="btn secondary" data-action="close-modal">留下继续</button><button class="btn danger" data-action="leave">离开房间</button>','leave');break;
  case'leave':await command('leave');closeModal();view='lobby';render();break;
  case'skin':prefs.skin=el.dataset.skin;save();render();toast('已保存当前浏览器的试穿效果。');break;
  case'map-info':mapDetails(el.dataset.map);break;case'retry-preview':await drawPreview();break;
  case'rules':rules();break;case'settings':settings();break;
  case'sound':prefs.sound=!prefs.sound;save();el.setAttribute('aria-label',prefs.sound?'关闭音效':'开启音效');toast(prefs.sound?'音效已开启':'音效已关闭');break;
  case'modal-sound':prefs.sound=!prefs.sound;el.textContent=prefs.sound?'已开启':'已关闭';save();break;
  case'close-modal':closeModal();break;
  case'reconnect':if(await network.restore(accept,setConnection)){toast('已重新连接本地服务。');}else{await network.logout();state=null;view='login';lastRoomId=null;closeModal();render();toast('请重新建立本地身份。');}break;
  case'logout':await network.logout();state=null;view='login';lastRoomId=null;closeModal();render();break;
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();sound();act(el.dataset.action,el).catch(error=>toast(error.message));});
document.addEventListener('submit',async event=>{event.preventDefault();try{
  if(event.target.id==='login-form'){if(busy)return;const name=$('#nickname').value.trim();if(!name){$('#login-error').textContent='请输入昵称。';return;}busy=true;event.target.querySelector('button[type=submit]').disabled=true;const data=await network.login(name,draftCharacter,accept,setConnection);state=data;prefs.character=draftCharacter;save();view='channels';busy=false;render();}
  else if(event.target.id==='config-form'){const name=$('#room-name').value.trim();if(!name){toast('房间名称不能为空。');return;}const config={name,mode:$('#room-mode').value,map:$('#room-map').value,bots:Number($('#room-bots').value),duration:Number($('#room-duration').value),channel};const info=mapInfo(config.map),humans=Number(event.target.dataset.humanCount)||1;if(!canPreviewMap(info)||!info.playableModes.includes(config.mode)||config.bots+humans>info.maxSeats){toast('请按地图人数与可用模式调整房间。');return;}if(event.target.dataset.create==='true')await network.create(config);else await command('config',config);closeModal();view='room';render();}
  else if(event.target.id==='chat-form'){const input=$('#chat-input'),text=input.value.trim();if(!text)return;await command('chat',{text});input.value='';updateChat();}
}catch(error){busy=false;if(view==='login'){const el=$('#login-error');if(el){el.hidden=false;el.textContent=error.message;}$('#login-form button[type=submit]')?.removeAttribute('disabled');}else toast(error.message);}});
document.addEventListener('change',event=>{if(event.target.id==='room-map')syncConfigMap();});

document.addEventListener('input',event=>{if(event.target.id==='volume'){prefs.volume=Number(event.target.value)/100;$('#volume-label').textContent=event.target.value+'%';save();}});
window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY)return;try{const latest=JSON.parse(event.newValue||'{}')||{};prefs.records=mergeRecords(latest.records);if(view==='records'&&state&&!modal)render();}catch{}});
const directions={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};
function sendMove(dir){if(view!=='battle'||modal||room()?.paused||room()?.game?.status!=='playing'||!connected)return;network.input({type:'move',dx:dir[0],dy:dir[1]}).catch(()=>{});lastInput=performance.now();}
document.addEventListener('keydown',event=>{if(modal){if(event.key==='Escape'&&modal!=='paused'){event.preventDefault();closeModal();return;}if(event.key==='Tab'){const f=[...modalRoot.querySelectorAll('button,input,select')].filter(e=>!e.disabled),first=f[0],last=f.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}return;}if(view!=='battle'||event.target.matches('input,select,textarea'))return;const key=event.key.toLowerCase();if(directions[key]||[' ','1','escape'].includes(key))event.preventDefault();if(directions[key]){pressed.add(key);if(!event.repeat)sendMove(directions[key]);}if(event.repeat)return;if(key===' ')act('bomb',{}).catch(error=>toast(error.message));if(key==='1')act('item',{}).catch(error=>toast(error.message));if(key==='escape'){if(owner())command('pause',{paused:true}).catch(error=>toast(error.message));else act('leave-confirm',{});}});
document.addEventListener('keyup',event=>pressed.delete(event.key.toLowerCase()));
document.addEventListener('pointerdown',event=>{const el=event.target.closest('[data-dir]');if(!el)return;event.preventDefault();held=el.dataset.dir.split(',').map(Number);el.setPointerCapture(event.pointerId);sendMove(held);});
for(const e of ['pointerup','pointercancel'])document.addEventListener(e,()=>held=null);
window.addEventListener('blur',()=>{pressed.clear();held=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden){pressed.clear();held=null;}});
function animate(now){if(view==='battle'&&room()?.game){paintBoard($('#arena'),room().game);const dir=held||directions[[...pressed][0]];if(dir&&now-lastInput>=90)sendMove(dir);}requestAnimationFrame(animate);}
await Promise.all([loadArt(),loadMapArt(),loadCharacterMotion().catch(()=>null),loadMapDirectory().catch(()=>null)]);if(await network.restore(accept,setConnection))view=room()?.game?'battle':room()?'room':'channels';render();requestAnimationFrame(animate);
